{
  "rewrites": [
    { "source": "/api/payments", "destination": "/api/payments-secure" },
    { "source": "/api/payments/quote", "destination": "/api/payments-secure?action=quote" },
    { "source": "/api/payments/start", "destination": "/api/payments-secure?action=start" },
    { "source": "/api/payments/verify", "destination": "/api/payments-secure?action=verify" },
    { "source": "/api/netcash", "destination": "/api/netcash-secure" },
    { "source": "/api/netcash/request", "destination": "/api/netcash-secure?action=request" },
    { "source": "/api/netcash/notify", "destination": "/api/netcash-secure?action=notify" },
    { "source": "/api/netcash/debicheck-postback", "destination": "/api/netcash-secure?action=debicheck_postback" }
  ],
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        { "key": "Strict-Transport-Security", "value": "max-age=31536000; includeSubDomains" },
        { "key": "X-Content-Type-Options", "value": "nosniff" },
        { "key": "X-Frame-Options", "value": "DENY" },
        { "key": "Referrer-Policy", "value": "strict-origin-when-cross-origin" },
        { "key": "Permissions-Policy", "value": "camera=(), microphone=(), geolocation=()" },
        { "key": "Cross-Origin-Opener-Policy", "value": "same-origin-allow-popups" },
        { "key": "Content-Security-Policy", "value": "default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' data: https://fonts.gstatic.com; img-src 'self' data: blob: https:; connect-src 'self' https://tfvfwrugdvjpgzoitwtp.supabase.co wss://tfvfwrugdvjpgzoitwtp.supabase.co; form-action 'self' https:; frame-src https:; upgrade-insecure-requests" }
      ]
    }
  ]
}
